    puts "WARNING: No top-level port 'clk' found; create_clock not applied."
}

set _rst_ports [get_ports -quiet {rst_n}]
if {[sizeof_collection $_rst_ports] > 0} {
    set_false_path -from $_rst_ports
} else {
    puts "WARNING: No top-level port 'rst_n' found; reset false-path not applied."
}

set bidir_ports {}
